// Parse the social media content from Claude API response
const socialResponse = $('Generate Social Media Content').first().json;
const newsletterResponse = $('Generate Newsletter Content').first().json;

// Extract the text content from Claude's response
let socialContent = {};
let newsletterContent = {};

try {
  const socialText = socialResponse.content[0].text;
  // Try to parse JSON from the response
  const jsonMatch = socialText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    socialContent = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  socialContent = {
    linkedin_post: socialResponse.content[0].text,
    twitter_post: 'Error parsing Twitter content',
    newsletter_content: 'Error parsing newsletter content'
  };
}

try {
  const newsletterText = newsletterResponse.content[0].text;
  const jsonMatch = newsletterText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    newsletterContent = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  newsletterContent = {
    subject_line: 'CTC Weekly Newsletter',
    preview_text: 'This week in creative technology',
    full_content: newsletterResponse.content[0].text
  };
}

const today = new Date().toISOString().split('T')[0];

return [
  {
    json: {
      date: today,
      platform: 'LinkedIn',
      content: socialContent.linkedin_post || '',
      status: 'Draft',
      type: 'Social Media'
    }
  },
  {
    json: {
      date: today,
      platform: 'Twitter/X',
      content: socialContent.twitter_post || '',
      status: 'Draft',
      type: 'Social Media'
    }
  },
  {
    json: {
      date: today,
      platform: 'Newsletter',
      subject: newsletterContent.subject_line || '',
      preview: newsletterContent.preview_text || '',
      content: JSON.stringify(newsletterContent, null, 2),
      status: 'Draft',
      type: 'Newsletter'
    }
  }
];
